create role anon; create role authenticated; create role service_role;
create schema auth; create schema storage; create schema net;
create table auth.users (id uuid primary key default gen_random_uuid(), email text, raw_user_meta_data jsonb default '{}');
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('app.uid', true), '')::uuid $$;
create table storage.buckets (id text primary key, name text, public boolean, file_size_limit bigint, allowed_mime_types text[]);
create table storage.objects (id uuid default gen_random_uuid(), bucket_id text, name text);
alter table storage.objects enable row level security;
create function storage.foldername(name text) returns text[] language sql as $$ select string_to_array(name, '/') $$;
create table net.calls (url text, body jsonb);
create function net.http_post(url text, body jsonb, headers jsonb) returns bigint language sql as $$ insert into net.calls values (url, body) returning 1::bigint $$;
create table public.profiles (id uuid primary key, email text, plan text default 'free', subscription_status text default 'inactive', current_period_end timestamptz, trial_ends_at timestamptz, weight numeric, height numeric, age int, gender text, activity numeric, goal text, kcal int, prot int, gluc int, lip int, weight_goal text, weight_entries text, current_plan text, subscription_id text);
create table public.consumed_meals (id uuid primary key default gen_random_uuid(), user_id uuid, name text, emoji text, macros jsonb, main_ingredients jsonb, meal_type text, source text, consumed_at timestamp);
create table public.credits (user_id uuid, balance int);
grant usage on schema public, auth, storage to anon, authenticated, service_role;
grant all on all tables in schema public to authenticated;
grant select on all tables in schema storage to authenticated;
grant execute on function auth.uid() to authenticated, anon, service_role;
alter default privileges in schema public grant all on tables to authenticated;
revoke insert, update, delete on public.profiles from authenticated;
grant insert (id, email, weight, height, age, gender, activity, goal, kcal, prot, gluc, lip, weight_goal, weight_entries, current_plan) on public.profiles to authenticated;
grant update (id, email, weight, height, age, gender, activity, goal, kcal, prot, gluc, lip, weight_goal, weight_entries, current_plan) on public.profiles to authenticated;
